// SINGLE SOURCE OF TRUTH for PromoMag settings. Both triggers pass through this node, and every
// other node reads it with $('Config').first().json.cfg - change chat IDs or categories here only.
const CFG = {
  ownerChatId: 8271099427,
  authorisedChatIds: [8271099427],
  defaultCategoryId: 1,
  // WordPress category IDs verified against https://promomag.co.uk/wp-json/wp/v2/categories
  categories: {
    'business-finance':   { label: 'Business',      wpId: 2,    keywords: ['business', 'finance'],     query: 'business OR finance news' },
    'entertainment-arts': { label: 'Entertainment', wpId: 105,  keywords: ['entertainment', 'arts'],   query: 'entertainment OR arts OR culture news' },
    'environment-nature': { label: 'Environment',   wpId: 162,  keywords: ['environment', 'nature'],   query: 'environment OR nature OR climate news' },
    'science-technology': { label: 'Science',       wpId: 296,  keywords: ['science', 'technology'],   query: 'science OR technology OR AI news' },
    'politics-global':    { label: 'Politics',      wpId: 5325, keywords: ['politics', 'global'],      query: 'UK politics OR global news OR parliament OR international affairs' }
  },
  // The daily scheduled run takes the next category in this list (by day of year).
  // Leave a single slug here to pin the schedule to one category.
  scheduleRotation: ['business-finance', 'science-technology', 'entertainment-arts', 'environment-nature', 'politics-global'],
  // Full-text research for the chosen topic. Limits protect the OpenAI rate limit: every 1,000
  // characters of source text is ~250 input tokens, read twice (dossier + fact check).
  research: {
    maxSources: 4,
    maxCharsPerSource: 6000,
    maxTotalChars: 18000,
    minFacts: 4,
    // 'jina' fetches through r.jina.ai (main text, no key needed); 'direct' fetches the page and
    // strips HTML in Build Source Pack. Switch here if the reader service is unavailable.
    reader: 'jina',
    // Ranked above news coverage when found.
    primaryDomains: ['gov.uk', 'parliament.uk', 'nhs.uk', 'ons.gov.uk', 'bankofengland.co.uk', 'europa.eu',
      'prnewswire.com', 'businesswire.com', 'globenewswire.com', 'newswire.ca', 'sec.gov']
  },
  models: { dossier: 'gpt-4o', factCheck: 'gpt-4o', revise: 'gpt-4o' },
  // Test hook: used ONLY by a manual run started from the Schedule Trigger (never by the 07:00
  // production run). Skips topic research and runs sourcing, dossier, writer and fact check on
  // this story. Set to null to disable.
  testTopic: {
    title: 'Naboo acquires UK meetings and events specialist pro-ven',
    search: 'Naboo acquires pro-ven',
    primary: 'Naboo',
    category: 'business-finance'
  }
};

return $input.all().map((item, i) => ({ json: { ...item.json, cfg: CFG }, pairedItem: { item: i } }));

// Explicit conversation state machine. The stage is authoritative and the message is
// interpreted in light of it, rather than the stage being guessed from keywords alone.
// Stages: IDLE -> AWAITING_TOPIC -> AWAITING_DIRECTION -> ARTICLE_READY
const raw = $input.item.json.message?.text || '';
const text = raw.toLowerCase().trim();
const chatId = $input.item.json.message.chat.id;
const sd = $getWorkflowStaticData('global');
const key = 'session_' + chatId;
const s = sd[key] || { stage: 'IDLE' };
if (!s.stage) s.stage = 'IDLE';

// Category keywords come from the Config node so the map lives in one place.
const cfg = $('Config').first().json.cfg;
const CATS = {};
for (const [slug, c] of Object.entries(cfg.categories)) {
  for (const kw of c.keywords) CATS[kw] = { label: c.label, slug, wpId: c.wpId, query: c.query };
}
const catPattern = new RegExp(Object.keys(CATS).join('|'));

const isReset     = text === '/start' || text === '/reset' ||
  /\b(new article|new post|start over|start again|fresh start|another article|write another)\b/.test(text);
const isStatusReq = text === '/status';

// Anchored at the start of the message so it cannot collide with ordinary prose. It must be
// tested before wantsWp, because that regex matches \bpost\b and \bwp\b - so a request like
// "image london skyline on the post" would otherwise route to WordPress.
const imageMatch = raw.trim().match(/^\/?image\b[:\s]*(.*)$/i);
const wantsImage  = !!imageMatch;
const imageQuery  = imageMatch ? imageMatch[1].trim() : '';

const wantsWp     = /\b(post|publish|wordpress|wp|send to wp|go live)\b/.test(text);
const wantsSocial = /\b(social|twitter|linkedin|facebook|instagram|hashtag|thumbnail)\b/.test(text);

let intent = 'unknown';
let statusMsg = '';
let newsQuery = '';
let isPublish = false;

if (isStatusReq) {
  intent = 'status';
} else if (isReset) {
  intent = 'reset';
  statusMsg = '\ud83d\udd04 Resetting your PromoMag session...';
} else if (wantsImage) {
  // Deliberately stage-independent: the target is whatever was published most recently,
  // which may be a scheduled post from a session that no longer exists.
  intent = imageQuery ? 'image' : 'unknown';
  statusMsg = '\ud83d\uddbc\ufe0f Searching for *' + imageQuery + '* and checking the latest post...';
} else if (wantsWp && s.stage === 'ARTICLE_READY') {
  intent = 'wordpress';
  isPublish = /\b(publish|go live|make it live|post live)\b/.test(text);
  statusMsg = isPublish
    ? '\ud83d\ude80 *Publishing to PromoMag...*'
    : '\ud83d\udce4 *Saving to PromoMag as a draft...*';
} else if (wantsSocial && s.stage === 'ARTICLE_READY') {
  intent = 'social';
  statusMsg = '\ud83d\udcf1 *Building your social pack...*';
} else if (wantsWp || wantsSocial) {
  // Asked to post or socialise before an article exists - explain rather than misread it.
  intent = 'unknown';
} else if (s.stage === 'IDLE') {
  const m = text.match(catPattern);
  if (m) {
    const c = CATS[m[0]];
    s.category = c;
    intent = 'category';
    newsQuery = c.query;
    statusMsg = '\ud83d\udd0d Researching trending *' + c.label + '* stories from Reuters, Bloomberg, BBC and more...\n\n_This takes 20\u201330 seconds._';
  }
} else if (s.stage === 'AWAITING_TOPIC') {
  intent = 'topic';
  statusMsg = '\ud83d\udccb Got it \u2014 reading the full source articles and extracting verified facts. _About a minute._';
} else if (s.stage === 'AWAITING_DIRECTION') {
  intent = 'direction';
  statusMsg = '\u270d\ufe0f *Writing the full article now...*\n\n_30\u201360 seconds._';
}

const IMAGE_HELP = 'Send *image <search term>* at any time to replace the featured image on the most recent post.';

const STAGE_HELP = {
  IDLE: 'Choose a category to begin:\n\nBusiness & Finance | Entertainment & Arts | Environment & Nature | Science & Technology | Politics & Global News\n\n' + IMAGE_HELP,
  AWAITING_TOPIC: 'Reply with a topic number (1\u20135) from the list above.',
  AWAITING_DIRECTION: 'Reply with the stance for the article:\n\n1. Supportive \u2014 argue in favour\n2. Critical \u2014 argue against\n3. Neutral \u2014 report it straight',
  ARTICLE_READY: 'Reply *post to WordPress* for a draft, *publish to WordPress* to go live, or *social* for a social pack.\n\n' + IMAGE_HELP
};

const guidanceMsg = '\ud83e\udd14 I did not follow that.\n\n' + (STAGE_HELP[s.stage] || STAGE_HELP.IDLE) +
  '\n\nSend /status to see where we are, or /reset to start again.';

const statusReport = '\ud83d\udccd *Session status*\n\nStage: `' + s.stage + '`\nCategory: ' +
  (s.category ? s.category.label : '\u2014') + '\nTopic: ' + (s.topicTitle || '\u2014') +
  '\nStance: ' + (s.direction || '\u2014') +
  '\nArticle drafted: ' + (s.stage === 'ARTICLE_READY' ? 'yes' : 'no') + '\n\n' + STAGE_HELP[s.stage];

sd[key] = s;

// Legacy field names retained so the existing branch conditions keep working unchanged.
// `query` duplicates imageQuery because the image sub-workflow reads j.query on a
// passthrough trigger, which does no field mapping of its own.
return [{ json: {
  chatId,
  originalText: raw,
  intent,
  stage: s.stage,
  isStatusReq: intent === 'status',
  isUnknown:   intent === 'unknown',
  isReset:     intent === 'reset',
  isWPIntent:  intent === 'wordpress',
  isCategory:  intent === 'category',
  isTopicPick: intent === 'topic',
  isDirection: intent === 'direction',
  isImage:     intent === 'image',
  imageQuery,
  query: imageQuery,
  newsQuery,
  isPublish,
  statusMsg,
  guidanceMsg,
  statusReport,
  category: s.category || null
}}];

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const sd = $getWorkflowStaticData('global');
const s = sd['session_' + chatId] || {};
const reply = (()=>{try{return $('Detect Stage').item.json.originalText || ''}catch(e){return ''}})();

// Direction used to be free text pasted straight into the prompt. A reply like "explore the
// process and criteria" is a research request wearing a writing instruction's clothes: the
// dossier held nothing on criteria, so the writer invented them. A stance, by contrast, can
// always be satisfied from whatever facts exist, which removes the invitation to invent.
const STANCES = {
  supportive: {
    label: 'Supportive',
    instruction: 'Argue in favour of the subject of this story. Use the dossier to build the strongest honest case for it: what it achieves, who benefits, why it is the right move. Do not invent supporting facts. Where a dossier fact cuts against the case, address it and explain why the case still holds rather than omitting it.'
  },
  critical: {
    label: 'Critical',
    instruction: 'Argue against the subject of this story. Use the dossier to build the strongest honest case that it is inadequate, misdirected, or will not achieve what it claims: what it omits, who it fails, what stays unresolved. Do not invent damaging facts and do not imply wrongdoing the dossier does not report. Criticise the decision, the policy or the claim \u2014 never the personal character of a named individual.'
  },
  neutral: {
    label: 'Neutral',
    instruction: 'Report the story straight. Set out what happened and what each named party\'s position is according to the dossier, and make clear which questions the dossier leaves open. Reach a judgement only where the facts support one.'
  }
};

const t = String(reply).toLowerCase();
let key = 'neutral';
if (/\b(1|one|support|supportive|positive|favourable|favorable|endorse|approve|in favour|in favor)\b/.test(t)) key = 'supportive';
else if (/\b(2|two|critic|critical|criticise|criticize|negative|sceptical|skeptical|against|oppose|opposed|challenge)\b/.test(t)) key = 'critical';
else if (/\b(3|three|neutral|balanced|impartial|objective|straight|report)\b/.test(t)) key = 'neutral';

const stance = STANCES[key];
s.stance = key;
s.direction = stance.label;
sd['session_' + chatId] = s;

const dossier = sd['dossier_' + chatId];
// Only a verified dossier may reach the writer. Sessions started before this change have none.
if (!dossier || !dossier.text) throw new Error('No verified dossier for this topic. Send /reset and choose the category again.');
const brief = dossier.text;
const date = sd['researchDate_' + chatId] ||
  new Date().toLocaleDateString('en-GB', {weekday:'long',day:'numeric',month:'long',year:'numeric'});

const promptText = '[CURRENT DATE: ' + date + ']\n\n' +
  'Write the complete article now. Do not ask questions, do not acknowledge, do not send a table of ' +
  'contents. Return the finished article starting with [BLOCK:METADATA].\n\n' +
  'Category: ' + ((s.category && s.category.label) || '') + '\n' +
  'Topic: ' + (s.topicTitle || '') + '\n\n' +
  'STANCE: ' + stance.label + '\n' + stance.instruction + '\n\n' +
  'The stance sets the argument, not the facts. It never licenses a claim the dossier does not ' +
  'support.\n\n' +
  '[VERIFIED DOSSIER - your only source of fact]\n\n' + brief;

return [{ json: { promptText, chatId, stance: key } }];

const CHUNK_SIZE = 3800;
const TELEGRAM_MAX = 4000;
const output = $input.item.json.output || '';
const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const items = [];

// Bound each block at [/BLOCK] OR at the next [BLOCK: marker, whichever comes first.
// Writing agents sometimes omit the closers entirely; the old 'take everything to the end'
// fallback made METADATA swallow the whole article and breach Telegram's 4096-char limit.
const extractBlock = (tag, text) => {
  const open = '[BLOCK:' + tag + ']';
  const start = text.indexOf(open);
  if (start === -1) return null;
  const contentStart = start + open.length;
  const closeIdx = text.indexOf('[/BLOCK]', contentStart);
  const nextIdx = text.indexOf('[BLOCK:', contentStart);
  const bounds = [closeIdx, nextIdx].filter(i => i !== -1);
  const end = bounds.length ? Math.min.apply(null, bounds) : text.length;
  return text.slice(contentStart, end).trim();
};

const parseField = (block, field) => {
  if (!block) return '';
  const lines = block.split('\n');
  for (const line of lines) {
    const prefix = field + ':';
    if (line.trim().startsWith(prefix)) return line.trim().slice(prefix.length).trim();
  }
  return '';
};

const chunkText = (text) => {
  const chunks = [];
  let remaining = String(text || '');
  while (remaining.length > 0) {
    let chunk = remaining.slice(0, CHUNK_SIZE);
    if (remaining.length > CHUNK_SIZE) {
      const lastNewline = chunk.lastIndexOf('\n');
      if (lastNewline > CHUNK_SIZE * 0.5) chunk = chunk.slice(0, lastNewline);
    }
    chunks.push(chunk.trim());
    remaining = remaining.slice(chunk.length).trim();
  }
  return chunks;
};

// Last line of defence: nothing leaves this node above the Telegram limit, whatever
// shape the model returned. A 400 here aborts the whole run before the image path.
const pushMsg = (text, generateImage) => {
  const parts = chunkText(text);
  for (let i = 0; i < parts.length; i++) {
    const isLast = i === parts.length - 1;
    items.push({ json: {
      chatId: chatId,
      text: parts[i].slice(0, TELEGRAM_MAX),
      generateImage: generateImage && isLast
    }});
  }
};

const metadataBlock = extractBlock('METADATA', output);
const articleBlock = extractBlock('ARTICLE', output);
const seoBlock = extractBlock('SEO', output);
const isCompleteArticle = !!(metadataBlock && articleBlock && seoBlock);
const hasBlocks = !!(metadataBlock || articleBlock || seoBlock);

const detectCategory = (meta) => {
  const author = parseField(meta, 'Author').toLowerCase();
  if (author.indexOf('business') !== -1 || author.indexOf('finance') !== -1) return 'business-finance';
  if (author.indexOf('entertainment') !== -1 || author.indexOf('arts') !== -1) return 'entertainment-arts';
  if (author.indexOf('environment') !== -1 || author.indexOf('nature') !== -1) return 'environment-nature';
  if (author.indexOf('science') !== -1 || author.indexOf('technology') !== -1) return 'science-technology';
  if (author.indexOf('politics') !== -1 || author.indexOf('global') !== -1 || author.indexOf('news') !== -1) return 'politics-global';
  return 'uncategorized';
};

if (isCompleteArticle) {
  const staticData = $getWorkflowStaticData('global');
  staticData['currentChatId'] = chatId; // reliable chatId for post-Merge nodes

  // Prefer the category the user actually chose this session over guessing from the byline.
  const sess = staticData['session_' + chatId] || {};
  const chosen = sess.category && sess.category.slug ? sess.category.slug : detectCategory(metadataBlock);

  staticData['article_' + chatId] = {
    title: parseField(metadataBlock, 'Title'),
    slug: parseField(metadataBlock, 'Slug'),
    excerpt: parseField(metadataBlock, 'Meta'),
    tags: parseField(metadataBlock, 'Tags'),
    imageDescription: parseField(metadataBlock, 'Image'),
    content: articleBlock,
    category: chosen,
    wpMediaId: 0,
    wpMediaUrl: null,
    // Set by Finalise Draft. Prepare Post refuses to publish an unverified article.
    verified: $input.item.json.verified === true,
    checkSummary: $input.item.json.checkSummary || 'Not fact-checked.',
    sources: $input.item.json.sources || []
  };

  // Advance the state machine so the WordPress and social gates open.
  sess.stage = 'ARTICLE_READY';
  staticData['session_' + chatId] = sess;
}

if (isCompleteArticle) {
  pushMsg('\ud83d\udcf0 *Article Brief*\n\n' + metadataBlock, false);
  pushMsg('\ud83d\udd0e *Fact check*\n\n' + String($input.item.json.checkSummary || 'Not fact-checked.').replace(/[_*\[\]`]/g, ' ') +
    ($input.item.json.verified === true ? '' : '\n\nThis article can be saved as a draft but will not be published.'), false);

  const clean = articleBlock
    .split('\n')
    .filter(function(l) { return !l.trim().match(/^#{1,6}\s/); })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const chunks = chunkText(clean);
  for (let i = 0; i < chunks.length; i++) {
    const label = chunks.length > 1
      ? '\u270d\ufe0f *Article Body (' + (i + 1) + '/' + chunks.length + ')*\n\n' + chunks[i]
      : '\u270d\ufe0f *Article Body*\n\n' + chunks[i];
    items.push({ json: { chatId: chatId, text: label.slice(0, TELEGRAM_MAX), generateImage: false } });
  }

  pushMsg('\ud83d\udce3 *Next Step*\n\n' + seoBlock, true);

} else if (hasBlocks) {
  const partialText = output
    .replace(/\[BLOCK:[^\]]+\]/g, '')
    .replace(/\[\/BLOCK\]/g, '')
    .trim();
  pushMsg(partialText || output, false);
} else {
  pushMsg(output || 'No response generated.', false);
}

return items.length > 0
  ? items
  : [{ json: { chatId: chatId, text: '\u26a0\ufe0f No content returned. Please try again.', generateImage: false } }];

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const sd = $getWorkflowStaticData('global');
const s = sd['session_' + chatId] || {};
s.stage = 'AWAITING_DIRECTION';
sd['session_' + chatId] = s;

const out = $input.first().json.output || '';
const text = '\ud83d\uddc2\ufe0f *Outline \u2014 ' + (s.topicTitle || '') + '*\n\n' + out;
return [{ json: { chatId, text } }];

const sd = $getWorkflowStaticData('global');

// Resolve the query from whichever path we arrived on, without relying on item pairing
// through the Telegram response that sits between Detect Stage and this node.
let q = '';
try { q = $('Detect Stage').first().json.newsQuery || ''; } catch (e) {}
if (!q) { try { q = $('Scheduled Config').first().json.newsQuery || ''; } catch (e) {} }
if (!q) q = sd['currentNewsQuery'] || 'top news';

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){return sd['currentChatId']}})();
sd['currentNewsQuery'] = q;

const newsUrl = 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) +
  '&hl=en-GB&gl=GB&ceid=GB:en';

return [{ json: { chatId, newsQuery: q, newsUrl } }];

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const staticData = $getWorkflowStaticData('global');
const category = (()=>{try{return $('Build News Query').first().json.newsQuery}catch(e){return ''}})() || '';

const now = new Date();
const currentDate = now.toLocaleDateString('en-GB', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

// Collect all RSS data from input items (could be multiple feeds merged)
let allRssData = '';
const inputItems = $input.all ? $input.all() : [$input.item];
for (const item of inputItems) {
  allRssData += (item.json.data || item.json.content || '') + '\n';
}

// Google News delivers <description> as CDATA-escaped HTML: &lt;a href="..."&gt;Headline&lt;/a&gt;.
// The old /<[^>]+>/g strip matched nothing because the angle brackets arrive as entities, so every
// description survived as ~300 chars of base64 Google redirect URL. Fifteen of those, resent on all
// five agent turns, were the bulk of the 13,566 input tokens that tripped OpenAI's rate limit.
const decodeEntities = (s) => String(s || '')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&apos;/g, "'")
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&');

const stripTags = (s) => decodeEntities(s)
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

const collected = [];
const seen = new Set();
const itemRegex = /<item>[\s\S]*?<\/item>/g;
let match;
while ((match = itemRegex.exec(allRssData)) !== null && collected.length < 60) {
  const rssItem = match[0];

  const titleMatch = rssItem.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) || rssItem.match(/<title>([\s\S]*?)<\/title>/);
  const rawTitle = titleMatch ? stripTags(titleMatch[1]) : '';
  if (!rawTitle || rawTitle.toLowerCase().includes('google news')) continue;
  if (seen.has(rawTitle)) continue;
  seen.add(rawTitle);

  const lastDash = rawTitle.lastIndexOf(' - ');
  const headline = lastDash > 0 ? rawTitle.slice(0, lastDash).trim() : rawTitle;
  const titleSource = lastDash > 0 ? rawTitle.slice(lastDash + 3).trim() : '';

  // Prefer the feed's own <source> element over the suffix parsed off the headline.
  const srcMatch = rssItem.match(/<source[^>]*>([\s\S]*?)<\/source>/);
  const source = (srcMatch ? stripTags(srcMatch[1]) : '') || titleSource;

  const pubDateMatch = rssItem.match(/<pubDate>([\s\S]*?)<\/pubDate>/);
  const pubDate = pubDateMatch ? pubDateMatch[1].trim() : '';
  const parsed = pubDate ? Date.parse(pubDate) : NaN;
  const ts = isNaN(parsed) ? 0 : parsed;

  // Once decoded, the description is the headline again wrapped in a link, carrying no information
  // the headline does not. Strip URLs and keep it only when it genuinely adds words.
  const descMatch = rssItem.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) || rssItem.match(/<description>([\s\S]*?)<\/description>/);
  let description = descMatch ? stripTags(descMatch[1]) : '';
  if (description) {
    description = description.replace(/https?:\/\/\S+/g, ' ').replace(/\s+/g, ' ').trim();
    const isEcho = norm(description).indexOf(norm(headline)) !== -1
      && description.length < headline.length + 40;
    if (isEcho || description.length < 40) description = '';
  }

  collected.push({ headline, source, pubDate, ts, description });
}

// Google News mixes evergreen and archive pages into a current-affairs query; a 2024 explainer
// presented as today's news is what produced topic briefs with no live hook. Prefer recent items,
// but never starve the agent: if too few survive the window, fall back to the full set.
const MAX_AGE_DAYS = 45;
const cutoff = now.getTime() - MAX_AGE_DAYS * 86400000;
let pool = collected.filter(a => a.ts >= cutoff);
const staleDropped = collected.length - pool.length;
let dateFiltered = true;
if (pool.length < 5) { pool = collected.slice(); dateFiltered = false; }
pool.sort((a, b) => b.ts - a.ts);
const articles = pool.slice(0, 15);

const fmtDate = (a) => a.ts
  ? new Date(a.ts).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
  : (a.pubDate || '');

// Format as research brief for the Research Agent
const researchInput = articles.map(function(a, i) {
  let entry = (i + 1) + '. ' + a.headline;
  if (a.source) entry += ' [' + a.source + ']';
  const d = fmtDate(a);
  if (d) entry += ' (' + d + ')';
  if (a.description) entry += '\n   ' + a.description.slice(0, 240);
  return entry;
}).join('\n\n');

// Save for later use in writing step
staticData['researchInput_' + chatId] = researchInput;
staticData['researchDate_' + chatId] = currentDate;
staticData['researchCategory_' + chatId] = category;

return [{ json: {
  chatId,
  currentDate,
  category,
  researchInput,
  articleCount: articles.length,
  staleDropped,
  dateFiltered,
  briefChars: researchInput.length
}}];

parameters.text:
=Category: {{ $json.category || 'general news' }}

Initial Google News headlines, as a starting point only:

{{ $json.researchInput }}

