const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const sd = $getWorkflowStaticData('global');

// Clear the state machine session plus every per-chat scratch key.
delete sd['session_' + chatId];
delete sd['article_' + chatId];
delete sd['categoryChosen_' + chatId];
delete sd['researchBrief_' + chatId];
delete sd['researchInput_' + chatId];
delete sd['researchTopics_' + chatId];
delete sd['topicBrief_' + chatId];

// Bump the counter so the memory session key changes too.
