  text: '\u2705 *Session reset.*\n\nAll previous article data cleared. Choose a category to begin:\n\nBusiness & Finance | Entertainment & Arts | Environment & Nature | Science & Technology | Politics & Global News'
}}];

// One parser for every consumer of the brief. Header-anchored, so a preamble such as "Here are
// five stories..." before TOPIC 1 is ignored instead of being taken as topic 1 - the v22 bug that
// failed every scheduled run and shifted interactive picks by one.
const parseTopics = (brief) => {
  const text = String(brief || '');
  const header = /^[ \t>#*_]*TOPIC\s+\d+\b[^\n]*$/gim;
  const marks = [];
  let m;
  while ((m = header.exec(text)) !== null) marks.push({ start: m.index, end: header.lastIndex });
  const topics = [];
  for (let i = 0; i < marks.length; i++) {
    const body = text.slice(marks[i].end, i + 1 < marks.length ? marks[i + 1].start : text.length).trim();
    const t = body.match(/^[ \t>*_-]*Title[*_]*\s*:[*_]*\s*(.+)$/im);
    const title = t ? t[1].replace(/[*_]+/g, '').trim() : '';
    // A slice with no title or too short to be a dossier is malformed - drop it rather than hand
    // the writer something it will fill with invention.
    if (title && body.length >= 80) topics.push({ title, body });
  }
  return topics.slice(0, 5);
};

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
