const field = (body, name) => (body.match(new RegExp('^[ \\t*_-]*' + name + '[*_]*\\s*:[*_]*\\s*(.+)$', 'im')) || [])[1] || '';
const mdSafe = (s) => String(s || '').replace(/[_*\[\]`]/g, ' ').replace(/\s+/g, ' ').trim();

