// Bound each block at [/BLOCK] or the next [BLOCK:, whichever comes first.
const block = (tag) => {
  const open = '[BLOCK:' + tag + ']';
  const s = output.indexOf(open);
  if (s === -1) return '';
  const cs = s + open.length;
  const ends = [output.indexOf('[/BLOCK]', cs), output.indexOf('[BLOCK:', cs)].filter(i => i !== -1);
  return output.slice(cs, ends.length ? Math.min(...ends) : output.length).trim();
};
