// Read the draft from this execution's run data. Static data is not reliable after a Wait resumes:
// in v22 it came back empty, so the dropped notice had no chat ID and the run errored.
const draft = $('Sched Store Media').first().json;
const q = ($input.first().json || {}).query || {};

const tokenOk = !!draft.approvalToken && String(q.token || '') === draft.approvalToken;
// A missing or wrong token is treated exactly like no approval at all: the draft is dropped.
const action = tokenOk ? String(q.action || '').toLowerCase() : '';
const approved = action === 'publish' || action === 'tailor';

if (action === 'tailor') {
  // Hand the draft to the interactive session so "post to WordPress" works on it.
  const sd = $getWorkflowStaticData('global');
  sd['article_' + draft.chatId] = {
    title: draft.title, slug: draft.slug, excerpt: draft.excerpt, tags: draft.tags,
    imageDescription: draft.imageDescription, content: draft.content, category: draft.category,
    wpMediaId: draft.wpMediaId, wpMediaUrl: null,
    verified: draft.verified === true, checkSummary: draft.checkSummary, sources: draft.sources || []
  };
  const s = sd['session_' + draft.chatId] || {};
  s.stage = 'ARTICLE_READY';
  s.topicTitle = draft.title;
  s.category = s.category || { label: draft.categoryLabel, slug: draft.category, wpId: draft.categoryId };
  sd['session_' + draft.chatId] = s;
}

return [{ json: { ...draft, action, approved, isPublish: action === 'publish', tokenOk, source: 'scheduled' } }];

const d = $('Approval Router').first().json;
const reason = d.tokenOk ? 'Unrecognised action.' : 'No valid approval within 6 hours.';
return [{ json: { chatId: d.chatId, safeTitle: d.safeTitle || '(untitled)', reason } }];

const sd = $getWorkflowStaticData('global');
const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const isScheduled = (()=>{try{return $('Scheduled Config').isExecuted===true}catch(e){return false}})();

// Same image logic for both paths; only where the article comes from differs.
const article = isScheduled ? $('Parse Scheduled Blocks').first().json : (sd['article_' + chatId] || {});
const title = article.title || '';
const imageDescription = article.imageDescription || '';

// Build the stock-photo query from the Image scene description, not the headline.
// A title like 'Momentum Builds to Curb AI Development' yielded 'momentum builds curb
// development' and returned construction-site photos for an article about AI safety.
const stopWords = new Set(['the','a','an','of','in','on','at','to','for','with','and','or','but',
  'is','are','was','were','be','been','being','has','have','had','do','does','did',
  'will','would','could','should','may','might','shall','its','it','this','that',
  'how','why','what','when','where','who','which','by','from','as','into','through',
  'below','above','over','under','their','there','while','also','very']);

// Vague qualifiers make Pixabay queries narrower without making them more relevant.
const qualifiers = new Set(['futuristic','towering','vivid','cinematic','detailed','beautiful',
  'stunning','dramatic','modern','large','small','tall','bright','dark','overcast','distant',
  'casting','displaying','showing','featuring','surrounded','filled','set','wide','close']);

const pickWords = (text, limit) => text.toLowerCase()
  .replace(/[^a-z0-9 ]/g, ' ')
  .split(/\s+/)
  .filter(w => w.length > 3 && !stopWords.has(w) && !qualifiers.has(w))
  .slice(0, limit)
  .join(' ');

// Three terms is the sweet spot: Pixabay ANDs them, so more terms means fewer hits
// and a needless fall through to DALL-E.
let query = pickWords(imageDescription, 3);
if (!query) query = pickWords(title, 3);
if (!query) query = 'editorial news';

// Descriptive filename and alt text instead of promomag-featured-<timestamp>.jpg - both feed image SEO.
const fileSlug = (article.slug || title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'promomag-featured';

return [{ json: { chatId, isScheduled, query, title, imageDescription, fileSlug, altText: title } }];

// Pixabay had nothing usable. Generate instead, from the same scene description.
const q = $('Build Pixabay Query').first().json;
const imageDescription = q.imageDescription || q.title || 'Professional editorial magazine photograph';

const imagePrompt = [
  'Professional editorial magazine header photograph for a web publication.',
  imageDescription,
  'Cinematic lighting, photojournalism aesthetic, widescreen 16:9 composition.',
  'No people, no faces, no portraits, no humans visible.',
  'Focus on objects, landscapes, technology, architecture, abstract concepts, or symbolic imagery.',
  'No text, no watermarks, no logos.'
].join(' ');

return [{ json: { chatId: q.chatId, imagePrompt } }];

// DALL-E image generated — extract URL as JSON (no binary yet)
// Binary download happens after Merge
const url = $json.data && $json.data[0] ? $json.data[0].url : null;
if (!url) throw new Error('DALL-E returned no image URL');
return [{ json: { imageUrl: url, source: 'dalle' } }];

const q = $('Build Pixabay Query').first().json;
const body = $input.item.json.body || $input.item.json;
const wpMediaId = body.id || 0;
const wpMediaUrl = body.source_url || (body.guid && (body.guid.rendered || body.guid.raw)) || null;

// The interactive draft lives in static data until the user posts it; record the image against it.
if (!q.isScheduled && wpMediaId) {
  const sd = $getWorkflowStaticData('global');
  const article = sd['article_' + q.chatId];
  if (article) { article.wpMediaId = wpMediaId; article.wpMediaUrl = wpMediaUrl; }
}

return [{ json: { chatId: q.chatId, isScheduled: q.isScheduled, wpMediaId, wpMediaUrl } }];

let q = {};
try { q = $('Build Pixabay Query').first().json; } catch (e) {}
const raw = $input.item.json || {};

// Extract error in whatever format n8n provides
let err = 'Unknown error';
if (raw.error) {
  err = typeof raw.error === 'string' ? raw.error : (raw.error.message || raw.error.description || JSON.stringify(raw.error).slice(0, 300));
} else if (raw.message) {
  err = raw.message;
} else if (raw.statusCode) {
  err = 'HTTP ' + raw.statusCode;
}
const safe = String(err).replace(/[_*\[\]`]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);

// Sourcing and generation are separate from the WP upload and the Telegram preview,
// so do not blame "generation" for what is usually an upload or send failure.
return [{ json: {
  chatId: q.chatId,
  isScheduled: !!q.isScheduled,
  wpMediaId: 0,
  text: '⚠️ *Featured image not attached*\n\nThe article itself is saved. You can still post it — reply *post to WordPress* — then add a featured image with *image <search term>*.\n\n_Error: ' + safe + '_'
}}];

// Single entry to publishing for both paths: interactive (from Retrieve Stored Article) and
// scheduled (from Approval Router). Everything downstream reads this node's output.
const cfg = $('Config').first().json.cfg;
const j = $json;
const isScheduled = j.source === 'scheduled';

const categoryId = j.categoryId || (cfg.categories[j.category] || {}).wpId || cfg.defaultCategoryId;

const toHtml = (raw) => String(raw || '')
  .split('\n')
  .filter(line => !line.trim().match(/^#{1,6}\s/))
  .join('\n')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, '<em>$1</em>')
  .replace(/^>\s?(.+)/gm, '<blockquote>$1</blockquote>')
  // The scheduled writer separates paragraphs with single newlines, the interactive one with blank lines.
  .split(isScheduled ? /\n+/ : /\n\n+/)
  .map(para => {
    const t = para.trim();
    if (!t) return '';
    if (t.startsWith('<blockquote>') || t.startsWith('<p>')) return t;
    return '<p>' + t.replace(/\n/g, '<br>') + '</p>';
  })
  .filter(Boolean)
  .join('\n\n');

// Source links come from the fetched URLs, never from the model.
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sources = (j.sources || []).filter(s => /^https?:\/\//i.test(s.url || ''));
const sourcesHtml = sources.length
  ? '\n\n<p><em>Sources: ' + sources.map(s => '<a href="' + esc(s.url) + '" rel="noopener">' + esc(s.outlet || new URL(s.url).hostname) + '</a>').join('; ') + '.</em></p>'
  : '';
const content = toHtml(j.content) + sourcesHtml;

// Hard gates: an article that fails any of these can be saved as a draft but never published.
const BRACKET_TAG = /\[[A-Z][^\]]+,\s+\w+\s+\d{4}\]/;
const blockers = [];
if (j.verified !== true) blockers.push('the fact check did not pass (' + (j.checkSummary || 'not fact-checked') + ')');
if (BRACKET_TAG.test(j.content || '')) blockers.push('the text contains bracket citation tags');
if (!sources.length) blockers.push('there are no source links');
const wantsPublish = !!j.isPublish;
const status = wantsPublish && !blockers.length ? 'publish' : 'draft';

// WordPress compares sanitised slugs, so sanitise before the duplicate check.
const slug = String(j.slug || j.title || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);

return [{ json: {
  chatId: j.chatId,
  source: isScheduled ? 'scheduled' : 'interactive',
  title: j.title || 'Untitled Article',
  content,
  slug,
  excerpt: j.excerpt || '',
  tags: j.tags || '',
  categoryId,
  wpMediaId: Number(j.wpMediaId) || 0,
  status,
  forcedDraftReason: wantsPublish && status === 'draft' ? blockers.join('; ') : ''
}}];

const names = [...new Set(String($json.tags || '')
  .split(',')
  .map(t => t.trim())
  .filter(t => t.length > 1))].slice(0, 8);

// One item per tag so Create WP Tag runs once for each. With no tags, pass one empty item through
// so the chain still reaches Post to WordPress; its failed tag call yields no ID and is filtered out.
return (names.length ? names : ['']).map(tagName => ({ json: { tagName } }));

// Create WP Tag runs with fullResponse, so a new tag arrives as { body: { id } } and an existing
// one as a 400 term_exists error whose term_id may only be inside a stringified message.
return $input.all().map(item => {
  const j = item.json || {};
  const b = j.body || j;
  let tagId = b.id || (b.data && b.data.term_id) || (j.error && j.error.data && j.error.data.term_id) || null;
  if (!tagId && j.error) {
    const raw = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    // The message is a JSON string inside a string, so the quotes arrive escaped (\"term_id\":5431);
    // the old /"term_id":/ pattern never matched and every existing tag was dropped.
    const m = String(raw).match(/term_id\W{0,4}:\s*(\d+)/);
    if (m) tagId = parseInt(m[1], 10);
  }
  return { json: { tagId } };
});

const p = $('Decide Post Action').first().json;
const tagIds = [...new Set(($json.tagItems || []).map(i => i.tagId).filter(Boolean))];
return [{ json: { ...p, tagIds } }];

const p = $('Decide Post Action').first().json;
const mdSafe = (s) => String(s || '').replace(/[_*\[\]`]/g, ' ').replace(/\s+/g, ' ').trim();

if (p.action === 'abort') {
  return [{ json: { chatId: p.chatId, text: '⚠️ *Not posted*\n\n' + mdSafe(p.title) + '\n\nReason: ' + mdSafe(p.abortReason) +
    (p.existingLink ? '\n\n🔗 [Existing post](' + p.existingLink + ')' : '') } }];
}

const j = $json || {};
const body = j.body || j;
if (j.error || !body.id) {
  const err = j.error ? (j.error.message || JSON.stringify(j.error)) : JSON.stringify(j);
  const retryHint = p.source === 'scheduled'
    ? 'The draft was not posted. Re-run the workflow or write it again from Telegram.'
    : 'The article is still stored. Reply *post to WordPress* to retry.';
  return [{ json: { chatId: p.chatId, text: '⚠️ *WordPress Post Failed*\n\n' + retryHint + '\n\nError: ' + mdSafe(err).slice(0, 200) } }];
}

const postId = body.id;
const link = body.link || ('https://promomag.co.uk/?p=' + postId);
const edit = 'https://promomag.co.uk/wp-admin/post.php?post=' + postId + '&action=edit';
const verb = p.action === 'update' ? 'updated' : 'saved';
let text = body.status === 'publish'
  ? '🚀 *Published on PromoMag*\n\n' + mdSafe(p.title) + '\n\n🔗 [View Article](' + link + ')\n🔗 [Edit in WP Admin](' + edit + ')'
  : '✅ *Draft ' + verb + ' on PromoMag*\n\n' + mdSafe(p.title) + '\n\n🔗 [Open in WP Admin](' + edit + ')\n\n_Review and publish when ready._';
if (p.forcedDraftReason) text += '\n\n⛔ *Kept as a draft, not published:* ' + mdSafe(p.forcedDraftReason);
if (p.action === 'update') text += '\n\nUpdated the existing draft (ID ' + postId + ') instead of creating a duplicate.';

return [{ json: { chatId: p.chatId, text, postId, link, status: body.status } }];

// Two searches per topic: the story itself, and the primary announcement. Bing's RSS endpoints are
// used because they return the publishers' real URLs; Google News only returns redirect links that
// cannot be resolved without a browser.
const j = $json;
const topic = j.topic || {};
const field = (name) => ((String(topic.body || '').match(new RegExp('^[ \\t*_-]*' + name + '[*_]*\\s*:[*_]*\\s*(.+)$', 'im')) || [])[1] || '').trim();
const clean = (s) => String(s || '').replace(/["\[\]]/g, ' ').replace(/\s+/g, ' ').trim();

const story = clean(field('Search') || topic.title);
const primary = clean(field('Primary'));
const queries = [
  { kind: 'news', url: 'https://www.bing.com/news/search?format=rss&mkt=en-GB&q=' + encodeURIComponent(story) },
  { kind: 'web', url: 'https://www.bing.com/search?format=rss&mkt=en-GB&q=' + encodeURIComponent(
      (primary && !/unknown/i.test(primary) ? primary + ' ' : '') + story + ' announcement') }
];

return queries.map(q => ({ json: { ...q, chatId: j.chatId, isScheduled: !!j.isScheduled, topicTitle: topic.title,
  primary, sourcesLine: field('Sources') } }));

const cfg = $('Config').first().json.cfg.research;
const req = $('Build Source Search').first().json;
const STOP = new Set(['the','a','an','of','in','on','at','to','for','with','and','or','its','as','by','from','after','over','into','new','says','said']);
const tokens = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !STOP.has(w));
const topicTokens = new Set(tokens(req.topicTitle));
const outletsNamed = String(req.sourcesLine || '').toLowerCase();
const primaryTokens = tokens(req.primary).filter(t => t !== 'unknown');

const decode = (s) => String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&').trim();
const BLOCKED = /(^|\.)(bing\.com|news\.google\.com|google\.com|msn\.com|youtube\.com|facebook\.com|x\.com|twitter\.com|linkedin\.com|instagram\.com|tiktok\.com|reddit\.com|wikipedia\.org)$/i;

const candidates = [];
const searches = $('Build Source Search').all();
$input.all().forEach((item, i) => {
  const kind = (searches[i] && searches[i].json.kind) || 'news';
  const xml = String(item.json.data || '');
  const re = /<item>([\s\S]*?)<\/item>/g;
  let m;
  while ((m = re.exec(xml)) !== null) {
    const block = m[1];
    const get = (tag) => { const r = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>', 'i')); return r ? decode(r[1]) : ''; };
    let url = get('link');
    // Bing wraps news links as .../apiclick.aspx?...&url=<encoded publisher URL>&...
    const wrapped = url.match(/[?&]url=([^&]+)/i);
    if (wrapped) { try { url = decodeURIComponent(wrapped[1]); } catch (e) {} }
    if (!/^https?:\/\//i.test(url)) continue;
    let host = '';
    try { host = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { continue; }
    if (BLOCKED.test(host)) continue;
    const title = get('title');
    const outlet = get('News:Source') || get('source') || host;
    const overlap = topicTokens.size ? tokens(title).filter(t => topicTokens.has(t)).length / topicTokens.size : 0;
    const isPrimary = cfg.primaryDomains.some(d => host === d || host.endsWith('.' + d))
      || (primaryTokens.length > 0 && primaryTokens.some(t => host.split('.').slice(0, -1).join('.').includes(t)));
    // Relevance first: an off-topic page is worse than one source fewer.
    if (overlap < 0.3 && !isPrimary) continue;
    const named = outletsNamed && (outletsNamed.includes(outlet.toLowerCase()) || outletsNamed.includes(host.split('.')[0]));
    const score = overlap * 4 + (isPrimary ? 5 : 0) + (named ? 2 : 0) + (kind === 'news' ? 0.5 : 0);
    candidates.push({ url, host, title, outlet, published: get('pubDate'), isPrimary, score: Math.round(score * 100) / 100 });
  }
});

// One page per site, best first.
candidates.sort((a, b) => b.score - a.score);
const seen = new Set();
const picked = [];
for (const c of candidates) {
  if (seen.has(c.host)) continue;
  seen.add(c.host);
  picked.push(c);
  if (picked.length >= cfg.maxSources) break;
}

const base = { chatId: req.chatId, isScheduled: req.isScheduled, topicTitle: req.topicTitle, candidateCount: candidates.length };
// Always emit at least one item so the chain reaches Parse Dossier, which reports "no sources".
if (!picked.length) return [{ json: { ...base, url: '', skip: true } }];
return picked.map((p, i) => ({ json: { ...base, ...p, sourceId: 'S' + (i + 1) } }));

const cfg = $('Config').first().json.cfg;
const picks = $('Pick Source URLs').all().map(i => i.json);
const first = picks[0] || {};

// Reader output is markdown (jina) or raw HTML (direct). Reduce both to article prose.
const fromHtml = (h) => String(h)
  .replace(/<(script|style|noscript|nav|footer|header|aside|form)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/(p|h[1-6]|li|div|br)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&rsquo;|&lsquo;/g, "'")
  .replace(/&ldquo;|&rdquo;/g, '"').replace(/&pound;/g, '£').replace(/&euro;/g, '€');
const tidy = (t) => t
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')            // images
  .replace(/\[([^\]]+)\]\((?:[^)(]|\([^)]*\))*\)/g, '$1') // links -> link text
  .split('\n').map(l => l.replace(/^[#>*\-\s]+/, '').trim())
  // Menus, share buttons and bylines are short lines with no sentence in them.
  .filter(l => l.length >= 40 || /[.!?:]["')]?$/.test(l) && l.length >= 15)
  .join('\n').replace(/\n{2,}/g, '\n').trim();
const BLOCKED_PAGE = /(access denied|just a moment|enable javascript|are you a robot|captcha|subscribe to (?:continue|read)|402 payment required)/i;

const sources = [];
let total = 0;
const notes = [];
$input.all().forEach((item, i) => {
  const p = picks[i] || {};
  if (!p.url) return;
  const raw = String(item.json.data || '');
  if (item.json.error || !raw) { notes.push(p.host + ': fetch failed'); return; }
  let text = /<html|<body|<div/i.test(raw.slice(0, 2000)) ? fromHtml(raw) : raw;
  const pub = (text.match(/^Published Time:\s*(.+)$/m) || [])[1] || p.published || '';
  text = text.replace(/^(Title|URL Source|Published Time|Markdown Content):.*$/gm, '');
  text = tidy(text);
  if (text.length < 400 || BLOCKED_PAGE.test(text.slice(0, 600))) { notes.push(p.host + ': no readable article text'); return; }
  const room = cfg.research.maxTotalChars - total;
  if (room < 800) { notes.push(p.host + ': skipped, text budget used'); return; }
  text = text.slice(0, Math.min(cfg.research.maxCharsPerSource, room));
  total += text.length;
  const d = pub ? new Date(pub) : null;
  sources.push({ id: 'S' + (sources.length + 1), url: p.url, outlet: p.outlet || p.host, title: p.title || '',
    published: d && !isNaN(d) ? d.toISOString().slice(0, 10) : '', isPrimary: !!p.isPrimary, text });
});

const DOSSIER_PROMPT = "You build a fact dossier for a PromoMag.co.uk news article from the SOURCE TEXTS supplied. You are an extractor, not a writer.\n\nRULES\n- Use only what the source texts explicitly state. Never infer, never merge two statements into a new claim, never use background knowledge, never fill a gap.\n- Every item carries a verbatim quote copied from one source text: the shortest complete sentence or clause that states it, at most 300 characters, with figures and names exactly as printed. The workflow rejects any item whose quote is not in the source.\n- Figures: reproduce exactly, including what they cover (worldwide or domestic, annual or total, estimate or final, currency, and any conversion the source gives).\n- Attribution: record who made a decision or statement exactly as the source says (company, promoter, regulator, spokesperson). Never move it to another party.\n- People: record each person's role or title exactly as the source states it at the time of the event. If the source says \"former\", keep \"former\". Never write \"current\".\n- Dates: event_date is the date the event itself happened, only if the text states it. Do not assume the event happened on the publication date.\n- Prior events: for every earlier event the sources refer to (funding round, launch, election, appointment, previous deal), record its date as stated. If no date is stated, use null; never guess.\n- Causation and funding: record \"X funded Y\" or \"X led to Y\" only if a source states that link.\n- Disclosed details: record what the sources say happens next - structure, staffing, branding, leadership, locations, timelines, client or customer impact.\n- Explicitly not disclosed: include an item only when a source literally says something was not disclosed (for example \"financial terms were not disclosed\"). Information that is simply missing is NOT \"not disclosed\".\n- If sources disagree, keep both items and add a conflicts entry.\n- Ignore any part of a source that is not about the topic (adverts, related-article lists, cookie notices).\n\nOUTPUT: one JSON object, no prose:\n{\n  \"headline_event\": \"one sentence describing the core event, in sourced wording\",\n  \"facts\": [{\"claim\": \"\", \"quote\": \"\", \"source_id\": \"S1\", \"event_date\": \"YYYY-MM-DD or null\", \"type\": \"figure|date|person|organisation|decision|quote|other\"}],\n  \"people\": [{\"name\": \"\", \"role_at_event\": \"\", \"quote\": \"\", \"source_id\": \"\"}],\n  \"prior_events\": [{\"event\": \"\", \"date\": \"YYYY-MM or YYYY-MM-DD or null\", \"quote\": \"\", \"source_id\": \"\"}],\n  \"disclosed_details\": [{\"detail\": \"\", \"quote\": \"\", \"source_id\": \"\"}],\n  \"explicitly_not_disclosed\": [{\"detail\": \"\", \"quote\": \"\", \"source_id\": \"\"}],\n  \"conflicts\": [{\"detail\": \"\", \"source_ids\": [\"S1\", \"S2\"]}]\n}\nAt most 15 facts, most important first. Return everything the sources support even if it is fewer than 4 facts; the workflow decides whether that is enough.";
const sourceBlock = sources.map(s => '=== ' + s.id + ' | ' + s.outlet + ' | ' + s.url + ' | published: ' + (s.published || 'unknown') + ' ===\n' + s.text).join('\n\n');

return [{ json: {
  chatId: first.chatId, isScheduled: !!first.isScheduled, topicTitle: first.topicTitle,
  sources, sourceChars: total, fetchNotes: notes, haveSources: sources.length > 0,
  request: {
    model: cfg.models.dossier, temperature: 0, max_tokens: 2500, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: DOSSIER_PROMPT },
      { role: 'user', content: 'TOPIC: ' + first.topicTitle + '\n\nSOURCE TEXTS:\n\n' + sourceBlock }
    ]
  }
}}];

// Normalise for quote matching: case, whitespace, curly quotes and dashes vary between the
// reader output and what a model copies back.
const norm = (s) => String(s || '').toLowerCase()
  .replace(/[‘’‚′]/g, "'").replace(/[“”„″]/g, '"')
  .replace(/[‐-―−]/g, '-').replace(/ /g, ' ')
  .replace(/[*_`]/g, '').replace(/\s+/g, ' ').trim();
// A quote counts as found if it appears verbatim (after normalising), or if one source sentence
// contains at least 90% of its words - this tolerates a dropped comma, not a changed figure.
const words = (s) => norm(s).replace(/[^a-z0-9%$£€.\- ]/g, ' ').split(/\s+/)
  .map(w => w.replace(/^[.\-]+|[.\-]+$/g, '')).filter(w => w.length > 1);
const quoteFound = (quote, text) => {
  const q = norm(quote);
  if (q.length < 12) return false;
  const t = norm(text);
  if (t.includes(q)) return true;
  const qw = words(quote);
  if (qw.length < 4) return false;
  const nums = qw.filter(w => /\d/.test(w));
  for (const sent of t.split(/(?<=[.!?])\s+|\n+/)) {
    const sw = new Set(words(sent));
    const hit = qw.filter(w => sw.has(w)).length / qw.length;
    // Every figure in the quote must be in the sentence: 90% overlap must not pass a changed number.
    if (hit >= 0.9 && nums.every(n => sw.has(n))) return true;
  }
  return false;
};

const cfg = $('Config').first().json.cfg;
const pack = $('Build Source Pack').first().json;
const sources = pack.sources || [];
const byId = Object.fromEntries(sources.map(s => [s.id, s]));
const chatId = pack.chatId;
const isScheduled = pack.isScheduled;

let d = {};
let llmError = '';
try {
  const content = $json.choices && $json.choices[0] && $json.choices[0].message.content;
  if (content) d = JSON.parse(content);
  else if ($json.error) llmError = String($json.error.message || $json.error).slice(0, 200);
} catch (e) { llmError = 'dossier JSON did not parse'; }

// Keep only items whose quote is really in the cited source. This is what stops invented facts,
// misread figures and made-up URLs: the URL comes from the fetch, never from the model.
const rejected = [];
const ground = (arr, label) => (Array.isArray(arr) ? arr : []).filter(x => {
  const s = byId[x.source_id];
  const ok = !!s && quoteFound(x.quote, s.text);
  if (!ok) rejected.push(label + ': ' + String(x.claim || x.detail || x.event || x.name || '').slice(0, 80));
  return ok;
}).map(x => ({ ...x, url: byId[x.source_id].url, outlet: byId[x.source_id].outlet, published: byId[x.source_id].published }));

const facts = ground(d.facts, 'fact');
const people = ground(d.people, 'person');
const prior = ground(d.prior_events, 'prior event');
const disclosed = ground(d.disclosed_details, 'detail');
const notDisclosed = ground(d.explicitly_not_disclosed, 'not disclosed');
const conflicts = Array.isArray(d.conflicts) ? d.conflicts : [];

const sufficient = facts.length >= cfg.research.minFacts;
const usedIds = new Set([...facts, ...people, ...prior, ...disclosed, ...notDisclosed].map(x => x.source_id));
const usedSources = sources.filter(s => usedIds.has(s.id));

// Plain-text dossier for the writer. No bracketed IDs: the writer copies whatever format it sees.
const L = [];
L.push('TOPIC: ' + pack.topicTitle);
if (d.headline_event) L.push('CORE EVENT: ' + d.headline_event);
L.push('', 'SOURCES');
usedSources.forEach(s => L.push('- ' + s.outlet + (s.isPrimary ? ' (primary source)' : '') + ', published ' + (s.published || 'date unknown')));
L.push('', 'FACTS (each confirmed verbatim in a source; the quote is the exact source wording)');
facts.forEach((f, i) => L.push((i + 1) + '. ' + f.claim + '\n   Source: ' + f.outlet + (f.event_date ? ' | event date: ' + f.event_date : '') + '\n   Quote: "' + f.quote + '"'));
if (people.length) { L.push('', 'PEOPLE (role as stated at the time of the event)'); people.forEach(p => L.push('- ' + p.name + ': ' + p.role_at_event + ' (' + p.outlet + ')')); }
if (prior.length) { L.push('', 'EARLIER EVENTS (with the date the source gives)'); prior.forEach(p => L.push('- ' + p.event + ': ' + (p.date || 'date not stated') + ' (' + p.outlet + ')')); }
if (disclosed.length) { L.push('', 'DISCLOSED DETAILS (what the sources say happens next)'); disclosed.forEach(x => L.push('- ' + x.detail + ' (' + x.outlet + ')')); }
L.push('', 'EXPLICITLY NOT DISCLOSED (only items a source says were withheld)');
if (notDisclosed.length) notDisclosed.forEach(x => L.push('- ' + x.detail + ' (' + x.outlet + ': "' + x.quote + '")'));
else L.push('- none');
if (conflicts.length) { L.push('', 'CONFLICTS BETWEEN SOURCES'); conflicts.forEach(c => L.push('- ' + c.detail)); }
const dossierText = L.join('\n');

const dossier = {
  topicTitle: pack.topicTitle, text: dossierText, facts, people, prior, disclosed, notDisclosed,
  sources: usedSources.map(s => ({ id: s.id, url: s.url, outlet: s.outlet, published: s.published, text: s.text })),
  rejected, sufficient
};

if (!isScheduled) {
  const sd = $getWorkflowStaticData('global');
  if (sufficient) sd['dossier_' + chatId] = dossier;
  else delete sd['dossier_' + chatId];
}

const reason = !sources.length ? 'no source article could be found and read' + (pack.fetchNotes && pack.fetchNotes.length ? ' (' + pack.fetchNotes.join('; ') + ')' : '')
  : llmError ? 'dossier extraction failed: ' + llmError
  : 'only ' + facts.length + ' fact(s) could be confirmed in the source text (minimum ' + cfg.research.minFacts + ')';

return [{ json: {
  chatId, isScheduled, sufficient,
  route: (isScheduled ? 'sched_' : 'chat_') + (sufficient ? 'ok' : 'fail'),
  reason: sufficient ? '' : reason,
  dossier,
  stats: { sources: sources.length, sourceChars: pack.sourceChars, facts: facts.length, rejected: rejected.length }
}}];

const d = $json.dossier;
return [{ json: { chatId: $json.chatId, promptText: 'Topic: ' + d.topicTitle + '

[VERIFIED DOSSIER]
' + d.text } }];

const mdSafe = (s) => String(s || '').replace(/[_*\[\]`]/g, ' ').replace(/\s+/g, ' ').trim();
const s = $getWorkflowStaticData('global')['session_' + $json.chatId] || {};
return [{ json: { chatId: $json.chatId, text: '⚠️ *Could not verify this story*

' + mdSafe(s.topicTitle) + '

' + mdSafe($json.reason) +
  '. Nothing was written.

Reply with another topic number, or send the category again for fresh topics.' } }];

const cfg = $('Scheduled Config').first().json;
const d = $json.dossier;
const date = $getWorkflowStaticData('global')['researchDate_' + cfg.chatId] || new Date().toDateString();
const promptText =
  '[CURRENT DATE: ' + date + ']\n\n' +
  'Write the complete article now. Do not ask questions, do not acknowledge. Return the finished article starting with [BLOCK:METADATA].\n\n' +
  'Category: ' + cfg.categoryLabel + '\n' +
  'Topic: ' + d.topicTitle + '\n\n' +
  '[VERIFIED DOSSIER - your only source of fact]\n\n' + d.text;
return [{ json: { promptText, chatId: cfg.chatId, topicTitle: d.topicTitle } }];

const mdSafe = (s) => String(s || '').replace(/[_*\[\]`]/g, ' ').replace(/\s+/g, ' ').trim();
const cfg = $('Scheduled Config').first().json;
return [{ json: { chatId: cfg.chatId, text: '⏭️ *Scheduled run skipped - ' + cfg.categoryLabel + '*\n\n' + mdSafe($json.dossier && $json.dossier.topicTitle) +
  '\n\n' + mdSafe($json.reason) + '. Nothing was written or published.' } }];

// Splits the writer's draft into blocks and builds the fact-check request against the fetched
// source texts. Shared by both paths: the scheduled run has the dossier in run data, the Telegram
// run (a later execution than the topic pick) reads it from static data.
const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const isScheduled = (()=>{try{return $('Scheduled Config').isExecuted===true}catch(e){return false}})();
let dossier = null;
try { if ($('Parse Dossier').isExecuted) dossier = $('Parse Dossier').first().json.dossier; } catch (e) {}
if (!dossier) dossier = $getWorkflowStaticData('global')['dossier_' + chatId] || null;
const cfg = $('Config').first().json.cfg;

const output = String($json.output || '');

const block = (tag) => {
  const open = '[BLOCK:' + tag + ']';
  const s = output.indexOf(open);
  if (s === -1) return '';
  const cs = s + open.length;
  const ends = [output.indexOf('[/BLOCK]', cs), output.indexOf('[BLOCK:', cs)].filter(i => i !== -1);
  return output.slice(cs, ends.length ? Math.min(...ends) : output.length).trim();
};
const meta = block('METADATA');
const body = block('ARTICLE');
const sources = (dossier && dossier.sources) || [];
const FACT_CHECK_PROMPT = "You are the fact-checker for PromoMag.co.uk. You receive an ARTICLE and the SOURCE TEXTS it must be based on. Check the article against the source texts only \u2014 never against your own knowledge.\n\nExtract every checkable claim in the article: names, roles and titles, organisations, figures and what they cover, dates, sequence and timing words (after, following, on the heels of, weeks later, recently), causation or funding links, who made a decision or statement, and any statement that something is undisclosed, unknown or unclear. Split compound sentences into separate claims. Skip pure opinion, but check any fact implied inside it.\n\nFor each claim return:\n- \"claim\": the claim as the article states it (short)\n- \"supported\": \"true\" when a source states it with the same meaning, scope and attribution; \"partial\" when a source supports part of it but the article changes a figure's coverage, the timing, the attribution, a role's tense, or adds causation; \"false\" when no source states it or a source contradicts it\n- \"evidence_quote\": the exact sentence from a source that supports or contradicts it, copied verbatim (\"\" if none)\n- \"source_url\": the URL of that source (\"\" if none)\n- \"fix\": for partial or false, the corrected wording the sources support, or \"remove\"\n\nStrict rules:\n- Saying something is undisclosed, unknown or unclear is \"false\" unless a source literally says it was not disclosed.\n- Timing or sequence words are \"partial\" unless the sources give both dates and they support the wording.\n- A role described as current is \"partial\" if the source gives it only as of an earlier date.\n- Figures must match exactly, including currency and what they cover.\n\nOutput one JSON object: {\"claims\": [ ... ], \"summary\": \"one sentence\"}";
const field = (f) => { for (const l of meta.split('\n')) if (l.trim().startsWith(f + ':')) return l.trim().slice(f.length + 1).trim(); return ''; };
const articleForCheck = 'TITLE: ' + field('Title') + '\nMETA: ' + field('Meta') + '\n\n' + body;

return [{ json: {
  chatId, isScheduled, output, hasDraft: !!(meta && body), body,
  sources, dossierText: dossier ? dossier.text : '', notDisclosed: dossier ? (dossier.notDisclosed || []) : [],
  request: {
    model: cfg.models.factCheck, temperature: 0, max_tokens: 3000, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: FACT_CHECK_PROMPT },
      { role: 'user', content: 'ARTICLE:\n' + articleForCheck + '\n\nSOURCE TEXTS:\n\n' +
        sources.map(s => '=== ' + s.url + ' | ' + s.outlet + ' | published ' + (s.published || 'unknown') + ' ===\n' + s.text).join('\n\n') }
    ]
  }
}}];

// Normalise for quote matching: case, whitespace, curly quotes and dashes vary between the
// reader output and what a model copies back.
const norm = (s) => String(s || '').toLowerCase()
  .replace(/[‘’‚′]/g, "'").replace(/[“”„″]/g, '"')
  .replace(/[‐-―−]/g, '-').replace(/ /g, ' ')
  .replace(/[*_`]/g, '').replace(/\s+/g, ' ').trim();
// A quote counts as found if it appears verbatim (after normalising), or if one source sentence
// contains at least 90% of its words - this tolerates a dropped comma, not a changed figure.
const words = (s) => norm(s).replace(/[^a-z0-9%$£€.\- ]/g, ' ').split(/\s+/)
  .map(w => w.replace(/^[.\-]+|[.\-]+$/g, '')).filter(w => w.length > 1);
const quoteFound = (quote, text) => {
  const q = norm(quote);
  if (q.length < 12) return false;
  const t = norm(text);
  if (t.includes(q)) return true;
  const qw = words(quote);
  if (qw.length < 4) return false;
  const nums = qw.filter(w => /\d/.test(w));
  for (const sent of t.split(/(?<=[.!?])\s+|\n+/)) {
    const sw = new Set(words(sent));
    const hit = qw.filter(w => sw.has(w)).length / qw.length;
    // Every figure in the quote must be in the sentence: 90% overlap must not pass a changed number.
    if (hit >= 0.9 && nums.every(n => sw.has(n))) return true;
  }
  return false;
};

// Deterministic checks that do not depend on the model's honesty.
const GATES = [
  { re: /\[[A-Z][^\]]+,\s+\w+\s+\d{4}\]/, why: 'bracket citation tag such as [Outlet, Month Year]' },
  { re: /[\[(](?:F|S)\d{1,2}[\])]/, why: 'internal dossier reference such as [S1] in the text' },
  { re: /https?:\/\//i, why: 'raw URL in the article body (source links are appended by the workflow)' }
];
const UNDISCLOSED = /\b(undisclosed|not (?:been |yet )?disclosed|yet to (?:be )?(?:disclose|reveal|announce)|remains? (?:unclear|unknown|to be seen)|it is (?:not )?(?:unclear|unknown))\b/i;

// Pass 1 of the fact check. The model's verdicts are not taken on trust: a "supported"
// claim whose evidence quote is not in a source is downgraded to partial.
const draft = $('Extract Draft').first().json;
const cfg = $('Config').first().json.cfg;
const sources = draft.sources || [];
const allText = sources.map(s => s.text).join('\n');

let claims = [];
let checkAvailable = false;
try {
  const content = $json.choices && $json.choices[0] && $json.choices[0].message.content;
  if (content) { claims = JSON.parse(content).claims || []; checkAvailable = true; }
} catch (e) { checkAvailable = false; }

claims = claims.map(c => {
  let verdict = String(c.supported).toLowerCase();
  if (verdict !== 'true' && verdict !== 'partial') verdict = 'false';
  let note = '';
  if (verdict === 'true' && !quoteFound(c.evidence_quote, allText)) { verdict = 'partial'; note = 'evidence quote not found in the sources'; }
  return { claim: String(c.claim || ''), verdict, evidence: String(c.evidence_quote || ''), url: String(c.source_url || ''), fix: String(c.fix || ''), note };
});

const problems = claims.filter(c => c.verdict !== 'true');
const gateIssues = [];
if (!draft.hasDraft) gateIssues.push('draft is missing the [BLOCK:METADATA] or [BLOCK:ARTICLE] block');
if (!sources.length) gateIssues.push('no source texts to check against');
if (!checkAvailable) gateIssues.push('fact check unavailable (OpenAI error or unparsable reply)');
for (const g of GATES) if (g.re.test(draft.body)) gateIssues.push(g.why);
// Each "undisclosed/unclear" sentence must be about something a source said was withheld. One
// genuinely undisclosed price must not license "operational changes remain undisclosed".
const GENERIC = new Set(['disclosed','undisclosed','disclose','details','detail','terms','were','been','with','that','this','from','have','which','about']);
const withheld = (draft.notDisclosed || []).map(x => words((x.detail || '') + ' ' + (x.quote || '')).filter(w => w.length > 3 && !GENERIC.has(w)));
for (const sent of String(draft.body).split(/(?<=[.!?])\s+|\n+/)) {
  if (!UNDISCLOSED.test(sent)) continue;
  const sw = new Set(words(sent));
  if (!withheld.some(ws => ws.some(w => sw.has(w)))) {
    gateIssues.push('says something is undisclosed/unclear that no source says was withheld: "' + sent.trim().slice(0, 100) + '"');
  }
}

const counts = {
  total: claims.length,
  supported: claims.filter(c => c.verdict === 'true').length,
  partial: claims.filter(c => c.verdict === 'partial').length,
  unsupported: claims.filter(c => c.verdict === 'false').length
};
const clean = checkAvailable && draft.hasDraft && sources.length > 0 && problems.length === 0 && gateIssues.length === 0;

const REVISE_PROMPT = "You correct a PromoMag.co.uk article after a fact check. You receive the ARTICLE (in [BLOCK:] format), the PROBLEMS found, and the VERIFIED DOSSIER.\n\nFor each problem: remove the claim, or replace it with the corrected wording given in the problem's fix or supported by the dossier. Remove every bracket citation tag, dossier reference and URL from the text. Do not add any new fact. Do not change sentences that have no problem, except to keep the prose grammatical after a removal. If a paragraph loses its only fact, delete the paragraph.\n\nReturn the complete corrected article in exactly the same [BLOCK:METADATA], [BLOCK:ARTICLE] and [BLOCK:SEO] format, including every closing [/BLOCK] tag, and nothing else. Correct the METADATA Title and Meta too if they repeat a problem.";
const problemList = [
  ...problems.map(p => '- ' + (p.verdict === 'false' ? 'UNSUPPORTED' : 'PARTIAL') + ': "' + p.claim + '"' + (p.fix ? ' -> fix: ' + p.fix : '') + (p.note ? ' (' + p.note + ')' : '')),
  ...gateIssues.map(g => '- FORMAT: ' + g)
].join('\n');

return [{ json: {
  pass: 1, clean, checkAvailable, counts, problems, gateIssues,
  chatId: draft.chatId, isScheduled: draft.isScheduled, output: draft.output, body: draft.body,
  sources, dossierText: draft.dossierText, notDisclosed: draft.notDisclosed,
  request: {
    model: cfg.models.revise, temperature: 0.2, max_tokens: 4000,
    messages: [
      { role: 'system', content: REVISE_PROMPT },
      { role: 'user', content: 'ARTICLE:\n' + draft.output + '\n\nPROBLEMS:\n' + problemList + '\n\nVERIFIED DOSSIER:\n' + draft.dossierText }
    ]
  }
}}];

// Splits the writer's draft into blocks and builds the fact-check request against the fetched
// source texts. Shared by both paths: the scheduled run has the dossier in run data, the Telegram
// run (a later execution than the topic pick) reads it from static data.
const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const isScheduled = (()=>{try{return $('Scheduled Config').isExecuted===true}catch(e){return false}})();
let dossier = null;
try { if ($('Parse Dossier').isExecuted) dossier = $('Parse Dossier').first().json.dossier; } catch (e) {}
if (!dossier) dossier = $getWorkflowStaticData('global')['dossier_' + chatId] || null;
const cfg = $('Config').first().json.cfg;

// Use the revision if it came back with blocks; otherwise re-check the original draft so the
// second pass still reports honestly.
const revised = $json.choices && $json.choices[0] && $json.choices[0].message.content;
const original = $('Assess Fact Check').first().json.output;
const output = String(revised && revised.includes('[BLOCK:ARTICLE]') ? revised : original);

const block = (tag) => {
  const open = '[BLOCK:' + tag + ']';
  const s = output.indexOf(open);
  if (s === -1) return '';
  const cs = s + open.length;
  const ends = [output.indexOf('[/BLOCK]', cs), output.indexOf('[BLOCK:', cs)].filter(i => i !== -1);
  return output.slice(cs, ends.length ? Math.min(...ends) : output.length).trim();
};
const meta = block('METADATA');
const body = block('ARTICLE');
const sources = (dossier && dossier.sources) || [];
const FACT_CHECK_PROMPT = "You are the fact-checker for PromoMag.co.uk. You receive an ARTICLE and the SOURCE TEXTS it must be based on. Check the article against the source texts only \u2014 never against your own knowledge.\n\nExtract every checkable claim in the article: names, roles and titles, organisations, figures and what they cover, dates, sequence and timing words (after, following, on the heels of, weeks later, recently), causation or funding links, who made a decision or statement, and any statement that something is undisclosed, unknown or unclear. Split compound sentences into separate claims. Skip pure opinion, but check any fact implied inside it.\n\nFor each claim return:\n- \"claim\": the claim as the article states it (short)\n- \"supported\": \"true\" when a source states it with the same meaning, scope and attribution; \"partial\" when a source supports part of it but the article changes a figure's coverage, the timing, the attribution, a role's tense, or adds causation; \"false\" when no source states it or a source contradicts it\n- \"evidence_quote\": the exact sentence from a source that supports or contradicts it, copied verbatim (\"\" if none)\n- \"source_url\": the URL of that source (\"\" if none)\n- \"fix\": for partial or false, the corrected wording the sources support, or \"remove\"\n\nStrict rules:\n- Saying something is undisclosed, unknown or unclear is \"false\" unless a source literally says it was not disclosed.\n- Timing or sequence words are \"partial\" unless the sources give both dates and they support the wording.\n- A role described as current is \"partial\" if the source gives it only as of an earlier date.\n- Figures must match exactly, including currency and what they cover.\n\nOutput one JSON object: {\"claims\": [ ... ], \"summary\": \"one sentence\"}";
const field = (f) => { for (const l of meta.split('\n')) if (l.trim().startsWith(f + ':')) return l.trim().slice(f.length + 1).trim(); return ''; };
const articleForCheck = 'TITLE: ' + field('Title') + '\nMETA: ' + field('Meta') + '\n\n' + body;

return [{ json: {
  chatId, isScheduled, output, hasDraft: !!(meta && body), body,
  sources, dossierText: dossier ? dossier.text : '', notDisclosed: dossier ? (dossier.notDisclosed || []) : [],
  request: {
    model: cfg.models.factCheck, temperature: 0, max_tokens: 3000, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: FACT_CHECK_PROMPT },
      { role: 'user', content: 'ARTICLE:\n' + articleForCheck + '\n\nSOURCE TEXTS:\n\n' +
        sources.map(s => '=== ' + s.url + ' | ' + s.outlet + ' | published ' + (s.published || 'unknown') + ' ===\n' + s.text).join('\n\n') }
    ]
  }
}}];

// Normalise for quote matching: case, whitespace, curly quotes and dashes vary between the
// reader output and what a model copies back.
const norm = (s) => String(s || '').toLowerCase()
  .replace(/[‘’‚′]/g, "'").replace(/[“”„″]/g, '"')
  .replace(/[‐-―−]/g, '-').replace(/ /g, ' ')
  .replace(/[*_`]/g, '').replace(/\s+/g, ' ').trim();
// A quote counts as found if it appears verbatim (after normalising), or if one source sentence
// contains at least 90% of its words - this tolerates a dropped comma, not a changed figure.
const words = (s) => norm(s).replace(/[^a-z0-9%$£€.\- ]/g, ' ').split(/\s+/)
  .map(w => w.replace(/^[.\-]+|[.\-]+$/g, '')).filter(w => w.length > 1);
const quoteFound = (quote, text) => {
  const q = norm(quote);
  if (q.length < 12) return false;
  const t = norm(text);
  if (t.includes(q)) return true;
  const qw = words(quote);
  if (qw.length < 4) return false;
  const nums = qw.filter(w => /\d/.test(w));
  for (const sent of t.split(/(?<=[.!?])\s+|\n+/)) {
    const sw = new Set(words(sent));
    const hit = qw.filter(w => sw.has(w)).length / qw.length;
    // Every figure in the quote must be in the sentence: 90% overlap must not pass a changed number.
    if (hit >= 0.9 && nums.every(n => sw.has(n))) return true;
  }
  return false;
};

// Deterministic checks that do not depend on the model's honesty.
const GATES = [
  { re: /\[[A-Z][^\]]+,\s+\w+\s+\d{4}\]/, why: 'bracket citation tag such as [Outlet, Month Year]' },
  { re: /[\[(](?:F|S)\d{1,2}[\])]/, why: 'internal dossier reference such as [S1] in the text' },
  { re: /https?:\/\//i, why: 'raw URL in the article body (source links are appended by the workflow)' }
];
const UNDISCLOSED = /\b(undisclosed|not (?:been |yet )?disclosed|yet to (?:be )?(?:disclose|reveal|announce)|remains? (?:unclear|unknown|to be seen)|it is (?:not )?(?:unclear|unknown))\b/i;

// Pass 2 of the fact check. The model's verdicts are not taken on trust: a "supported"
// claim whose evidence quote is not in a source is downgraded to partial.
const draft = $('Extract Revised Draft').first().json;
const cfg = $('Config').first().json.cfg;
const sources = draft.sources || [];
const allText = sources.map(s => s.text).join('\n');

let claims = [];
let checkAvailable = false;
try {
  const content = $json.choices && $json.choices[0] && $json.choices[0].message.content;
  if (content) { claims = JSON.parse(content).claims || []; checkAvailable = true; }
} catch (e) { checkAvailable = false; }

claims = claims.map(c => {
  let verdict = String(c.supported).toLowerCase();
  if (verdict !== 'true' && verdict !== 'partial') verdict = 'false';
  let note = '';
  if (verdict === 'true' && !quoteFound(c.evidence_quote, allText)) { verdict = 'partial'; note = 'evidence quote not found in the sources'; }
  return { claim: String(c.claim || ''), verdict, evidence: String(c.evidence_quote || ''), url: String(c.source_url || ''), fix: String(c.fix || ''), note };
});

const problems = claims.filter(c => c.verdict !== 'true');
const gateIssues = [];
if (!draft.hasDraft) gateIssues.push('draft is missing the [BLOCK:METADATA] or [BLOCK:ARTICLE] block');
if (!sources.length) gateIssues.push('no source texts to check against');
if (!checkAvailable) gateIssues.push('fact check unavailable (OpenAI error or unparsable reply)');
for (const g of GATES) if (g.re.test(draft.body)) gateIssues.push(g.why);
// Each "undisclosed/unclear" sentence must be about something a source said was withheld. One
// genuinely undisclosed price must not license "operational changes remain undisclosed".
const GENERIC = new Set(['disclosed','undisclosed','disclose','details','detail','terms','were','been','with','that','this','from','have','which','about']);
const withheld = (draft.notDisclosed || []).map(x => words((x.detail || '') + ' ' + (x.quote || '')).filter(w => w.length > 3 && !GENERIC.has(w)));
for (const sent of String(draft.body).split(/(?<=[.!?])\s+|\n+/)) {
  if (!UNDISCLOSED.test(sent)) continue;
  const sw = new Set(words(sent));
  if (!withheld.some(ws => ws.some(w => sw.has(w)))) {
    gateIssues.push('says something is undisclosed/unclear that no source says was withheld: "' + sent.trim().slice(0, 100) + '"');
  }
}

const counts = {
  total: claims.length,
  supported: claims.filter(c => c.verdict === 'true').length,
  partial: claims.filter(c => c.verdict === 'partial').length,
  unsupported: claims.filter(c => c.verdict === 'false').length
};
const clean = checkAvailable && draft.hasDraft && sources.length > 0 && problems.length === 0 && gateIssues.length === 0;

const REVISE_PROMPT = "You correct a PromoMag.co.uk article after a fact check. You receive the ARTICLE (in [BLOCK:] format), the PROBLEMS found, and the VERIFIED DOSSIER.\n\nFor each problem: remove the claim, or replace it with the corrected wording given in the problem's fix or supported by the dossier. Remove every bracket citation tag, dossier reference and URL from the text. Do not add any new fact. Do not change sentences that have no problem, except to keep the prose grammatical after a removal. If a paragraph loses its only fact, delete the paragraph.\n\nReturn the complete corrected article in exactly the same [BLOCK:METADATA], [BLOCK:ARTICLE] and [BLOCK:SEO] format, including every closing [/BLOCK] tag, and nothing else. Correct the METADATA Title and Meta too if they repeat a problem.";
const problemList = [
  ...problems.map(p => '- ' + (p.verdict === 'false' ? 'UNSUPPORTED' : 'PARTIAL') + ': "' + p.claim + '"' + (p.fix ? ' -> fix: ' + p.fix : '') + (p.note ? ' (' + p.note + ')' : '')),
  ...gateIssues.map(g => '- FORMAT: ' + g)
].join('\n');

return [{ json: {
  pass: 2, clean, checkAvailable, counts, problems, gateIssues,
  chatId: draft.chatId, isScheduled: draft.isScheduled, output: draft.output, body: draft.body,
  sources, dossierText: draft.dossierText, notDisclosed: draft.notDisclosed,
  request: {
    model: cfg.models.revise, temperature: 0.2, max_tokens: 4000,
    messages: [
      { role: 'system', content: REVISE_PROMPT },
      { role: 'user', content: 'ARTICLE:\n' + draft.output + '\n\nPROBLEMS:\n' + problemList + '\n\nVERIFIED DOSSIER:\n' + draft.dossierText }
    ]
  }
}}];

// The draft that leaves this node is the last one checked, with a verdict that Prepare Post enforces:
// unverified drafts can be saved as WordPress drafts but never published.
let a = $('Assess Fact Check').first().json;
try { if ($('Assess Fact Check (2nd pass)').isExecuted) a = $('Assess Fact Check (2nd pass)').first().json; } catch (e) {}
const first = $('Assess Fact Check').first().json;
const verified = !!a.clean;
const revised = a.pass === 2;

const c = a.counts;
let summary = (verified ? '✅ Fact check passed' : '⛔ Fact check failed') +
  (revised ? ' after one revision' : '') + ': ' + c.supported + ' of ' + c.total + ' claims supported by the sources';
if (c.partial) summary += ', ' + c.partial + ' partial';
if (c.unsupported) summary += ', ' + c.unsupported + ' unsupported';
summary += '.';
if (revised && first.counts) summary += ' First draft had ' + (first.counts.partial + first.counts.unsupported) + ' problem claim(s).';
const issues = [...a.gateIssues, ...a.problems.slice(0, 3).map(p => (p.verdict === 'false' ? 'unsupported: ' : 'partial: ') + p.claim)];
if (!verified && issues.length) summary += ' Issues: ' + issues.join('; ') + '.';

return [{ json: {
  chatId: a.chatId, isScheduled: a.isScheduled, output: a.output, verified, checkSummary: summary,
  factCheck: { pass: a.pass, counts: c, problems: a.problems, gateIssues: a.gateIssues, firstPass: first.counts },
  sources: (a.sources || []).map(s => ({ url: s.url, outlet: s.outlet, published: s.published }))
}}];

// One article, one post. A draft with the same slug is updated in place (this is what turned
// "post to WordPress" then "publish" into two posts); a live post is never overwritten.
const p = $('Prepare Post').first().json;
const res = $json || {};
let action = 'create', existingId = null, abortReason = '', existingLink = '';

if (res.error || !Array.isArray(res.body)) {
  action = 'abort';
  abortReason = 'could not check WordPress for an existing post with this slug, so nothing was posted. Try again in a minute.';
} else if (res.body.length) {
  const e = res.body[0];
  existingLink = e.link || '';
  if (['publish', 'future', 'private'].includes(e.status)) {
    action = 'abort';
    abortReason = 'a post with this slug is already ' + (e.status === 'publish' ? 'live' : e.status) + ' (ID ' + e.id + '). Nothing was changed; edit it in WP Admin instead.';
    existingId = e.id;
  } else {
    action = 'update';
    existingId = e.id;
  }
}

return [{ json: { ...p, action, existingId, existingLink, abortReason } }];
